@Composable
private fun GenderChip(
 gender: Gender,
 isSelected: Boolean,
 onClick: () -> Unit,
 modifier: Modifier = Modifier
) {
 Card(
 modifier = modifier
 .height(60.dp)
 .clickable { onClick() },
 shape = RoundedCornerShape(12.dp),
 colors = CardDefaults.cardColors(
 containerColor = if (isSelected) PrimaryGreen.copy(alpha = 0.1f) else Color.White
 ),
 border = if (isSelected) {
 ButtonDefaults.outlinedButtonBorder.copy(
 brush = Brush.linearGradient(colors = listOf(PrimaryGreen, PrimaryGreen)),
 width = 2.dp
 )
 } else null
 ) {
 Row(
 modifier = Modifier
 .fillMaxSize()
 .padding(12.dp),
 horizontalArrangement = Arrangement.Center,
 verticalAlignment = Alignment.CenterVertically
 ) {
 Icon(
 imageVector = gender.icon,
 contentDescription = null,
 tint = if (isSelected) PrimaryGreen else TextSecondary,
 modifier = Modifier.size(20.dp)
 )
 Spacer(modifier = Modifier.width(8.dp))
 Text(
 text = gender.label,
 fontSize = 14.sp,
 fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal,
 color = if (isSelected) PrimaryGreen else TextPrimary
 )
 }
 }
}

@Composable
private fun ActivityLevelCard(
 level: ActivityLevel,
 isSelected: Boolean,
 onClick: () -> Unit
) {
 Card(
 modifier = Modifier
 .fillMaxWidth()
 .clickable { onClick() },
 shape = RoundedCornerShape(12.dp),
 colors = CardDefaults.cardColors(
 containerColor = if (isSelected) PrimaryGreen.copy(alpha = 0.1f) else Color.White
 ),
 border = if (isSelected) {
 ButtonDefaults.outlinedButtonBorder.copy(
 brush = Brush.linearGradient(colors = listOf(PrimaryGreen, SecondaryBlue)),
 width = 2.dp
 )
 } else null,
 elevation = CardDefaults.cardElevation(
 defaultElevation = if (isSelected) 2.dp else 1.dp
 )
 ) {
 Row(
 modifier = Modifier
 .fillMaxWidth()
 .padding(16.dp),
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = Arrangement.spacedBy(12.dp)
 ) {
 Icon(
 imageVector = level.icon,
 contentDescription = null,
 tint = if (isSelected) PrimaryGreen else TextSecondary,
 modifier = Modifier.size(24.dp)
 )

 Column(modifier = Modifier.weight(1f)) {
 Text(
 text = level.title,
 fontSize = 15.sp,
 fontWeight = FontWeight.SemiBold,
 color = if (isSelected) PrimaryGreen else TextPrimary
 )
 Text(
 text = level.description,
 fontSize = 12.sp,
 color = TextSecondary,
 lineHeight = 16.sp
 )
 }

 if (isSelected) {
 Icon(
 imageVector = Icons.Default.CheckCircle,
 contentDescription = null,
 tint = PrimaryGreen,
 modifier = Modifier.size(20.dp)
 )
 }
 }
 }
}

